import re

EMAIL = re.compile(r'([A-Za-z0-9])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})')
PHONE = re.compile(r'\+7\d{8}(\d{2})')


def mask_pii(text: str) -> str:
    text = EMAIL.sub(r'\1***@\2', text)
    return PHONE.sub(r'+7*******\1', text)
